from pathlib import Path
import json,hashlib,os,statistics,datetime
root=Path('/home/holo/line');base=Path('/tmp/engine-nursery-20261106');prefix='engine-nursery-20261106';out=root/'docs/research';raw=root/'generated'/prefix
results={}
for name in ['fixed-screen','larger','cold']:
 p=base/name/'result.json';r=json.loads(p.read_text());assert r['complete'],name
 results[name]=r
ns=statistics.median(s['nsPerFrame'] for s in results['fixed-screen']['samples'] if s['arm']==1)
decision={'recordedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'adopted':False,'reason':'Larger cold-process peak RSS increased from 436.11328125 to 507.32421875 MiB, exceeding the prospective 1.15 ratio bound. The driver stopped before warmed-resource checks and confirmation. No production runtime configuration retained.','screenCandidateMedianNsPerChargedFrame':ns,'absoluteTargetMet':False,'timingScope':'Established compileHandoff clock; five warmups and three measured compiles. No confirmation performed.','correctness':'Full structural check and complete checkpoint equality for cells 61/62 passed; exact track/work in all warmup, measured and resource compiles.','excluded':'Initial screen is invalid qualification evidence: frozen configuration and control identity were incomplete; corrected before the fresh fixed screen.'}
(base/'decision.json').write_text(json.dumps(decision,indent=2)+'\n')
for name,r in results.items(): (out/f'{prefix}-{name}.json').write_text(json.dumps(r,indent=2)+'\n')
(out/f'{prefix}-invalid-screen.json').write_text((base/'screen/result.json').read_text())
files={};artifacts={}
paths=[p for p in base.iterdir() if p.is_file() and p.suffix in ['.json','.log','.mts','.mjs','.py','.ts','.patch'] and p.name!='last-cold-worker.json']
paths += [base/'runner/.npmrc',base/'runner/tools/measure/engine_ab.ts',base/'runner/tools/measure/engine_sources.ts']
paths += [base/arm/f'baseline-{cell}.json' for arm in ['reference','candidate'] for cell in [61,62]]
for p in sorted(paths):
 data=p.read_bytes();entry={'sha256':hashlib.sha256(data).hexdigest(),'bytes':len(data),'data':json.loads(data) if p.suffix=='.json' else data.decode()};files[str(p.relative_to(base))]=entry
for arm in ['reference','candidate']:
 for cell in [61,62]:
  p=base/arm/f'checkpoint-{cell}.v8';data=p.read_bytes();rel=p.relative_to(base);dest=raw/rel;dest.parent.mkdir(parents=True,exist_ok=True)
  if not dest.exists():os.link(p,dest)
  artifacts[str(rel)]={'sha256':hashlib.sha256(data).hexdigest(),'bytes':len(data)}
(out/f'{prefix}-diagnostics.json').write_text(json.dumps({'decision':decision,'files':files,'localArtifacts':artifacts},indent=2)+'\n')
print(json.dumps(decision,indent=2))
for name,r in results.items():
 print(name,r['decision'],[statistics.median(s['nsPerFrame'] for s in r['samples'] if s['arm']==a) for a in [0,1]])
print('Exact measured/warmup/cold compiles:',sum(sum(len(s['iterations']) for s in r['samples'])+sum(len(c['arms']) for c in r['resources']) for r in results.values()))

