        const bytes = arms[arm].get(name);
        if (bytes === undefined) continue;
        const path = join(candidate, name);
        mkdirSync(dirname(path), {recursive: true});
        writeFileSync(path, bytes);
      }
      active = arm;
    },
  };
}

